// NoxChatControlServiceServer is the server API for NoxChatControlService service.
// All implementations must embed UnimplementedNoxChatControlServiceServer
// for forward compatibility.
//
// ==============================================================================
// NoxChatControlService
// Full control plane for NoxAI / NoxChat node administration, telemetry,
// direct interaction, memories, libraries, raw API payloads, and jobs.
// ==============================================================================
type NoxChatControlServiceServer interface {
	// Handshake, Node Info, Transport Compression Stats, and Live Config
	GetNodeStatus(context.Context, *NoxNodeStatusRequest) (*NoxNodeStatusResponse, error)
	UpdateControlConfig(context.Context, *NoxUpdateControlConfigRequest) (*NoxNodeStatusResponse, error)
	// Asynchronous Zstd-Chunked Live Streams (1MB State/Telemetry Buffer / 8MB Log/API Buffer)
	SubscribeState(*NoxStateSubscriptionRequest, grpc.ServerStreamingServer[NoxStateChunk]) error
	SubscribeLogsAndApi(*NoxLogApiSubscriptionRequest, grpc.ServerStreamingServer[NoxLogApiChunk]) error
	// Historical Usage & Python Runtime Telemetry Query (LTTB Downsampled for MetricHistoryChartControl)
	QueryTelemetryRange(context.Context, *RangeQueryRequest) (*RangeQueryResponse, error)
	// Historical Spool Paging (from 1GB Server-Side WAL Spool when store_raw_logs is enabled)
	GetSpoolStats(context.Context, *NoxSpoolStatsRequest) (*NoxSpoolStatsResponse, error)
	SearchLogs(context.Context, *NoxSearchLogsRequest) (*NoxSearchLogsResponse, error)
	QueryLogChunks(context.Context, *LogChunkQuery) (*LogChunkResponse, error)
	QueryApiCallChunks(context.Context, *NoxApiCallChunkQuery) (*NoxApiCallChunkResponse, error)
	GetApiCallDetail(context.Context, *NoxApiCallDetailRequest) (*NoxRawApiCallRecord, error)
	QueryChatTrace(context.Context, *NoxChatTraceRequest) (*NoxChatTraceResponse, error)
	ClearSpool(context.Context, *NoxClearSpoolRequest) (*NoxClearSpoolResponse, error)
	// Direct Chat Interaction (User: "MADTOM", UserID: "Control Center")
	SendDirectMessage(*NoxDirectMessageRequest, grpc.ServerStreamingServer[NoxDirectTurnEvent]) error
	GetChatHistory(context.Context, *NoxChatHistoryRequest) (*NoxChatHistoryResponse, error)
	ListChats(context.Context, *NoxListChatsRequest) (*NoxListChatsResponse, error)
	// RAG, Atomic Memories & Hot Memory Inspection + Modification
	QueryMemories(context.Context, *NoxMemoryQueryRequest) (*NoxMemoryQueryResponse, error)
	SearchMemoriesHybrid(context.Context, *NoxHybridSearchRequest) (*NoxHybridSearchResponse, error)
	UpsertMemory(context.Context, *NoxUpsertMemoryRequest) (*NoxMemoryMutationResponse, error)
	DeleteMemory(context.Context, *NoxDeleteMemoryRequest) (*NoxMemoryMutationResponse, error)
	ListHotMemories(context.Context, *NoxHotMemoryRequest) (*NoxHotMemoryResponse, error)
	UpsertHotMemory(context.Context, *NoxUpsertHotMemoryRequest) (*NoxHotMemoryResponse, error)
	DeleteHotMemory(context.Context, *NoxDeleteHotMemoryRequest) (*NoxHotMemoryResponse, error)
	// Stickers, GIFs, Libraries & Vector Inspection + Modification
	QueryMediaLibrary(context.Context, *NoxMediaQueryRequest) (*NoxMediaQueryResponse, error)
	GetMediaAssetPreview(context.Context, *NoxMediaPreviewRequest) (*NoxMediaPreviewResponse, error)
	MutateMediaItem(context.Context, *NoxMediaMutationRequest) (*NoxMediaMutationResponse, error)
	ManageMediaPin(context.Context, *NoxMediaPinRequest) (*NoxMediaMutationResponse, error)
	TriggerStickerPackAnalysis(context.Context, *NoxAnalyzePackRequest) (*NoxAnalyzePackResponse, error)
	ForceAddSticker(context.Context, *NoxForceAddStickerRequest) (*NoxMediaMutationResponse, error)
	// Active Jobs & Vector Store Explorer
	GetActiveJobs(context.Context, *NoxActiveJobsRequest) (*NoxActiveJobsResponse, error)
	InspectVectors(context.Context, *NoxVectorInspectRequest) (*NoxVectorInspectResponse, error)
	// Chat Images (Image Studio storage; images are strictly chat-bound)
	ListChatImages(context.Context, *NoxListChatImagesRequest) (*NoxListChatImagesResponse, error)
	GetChatImage(context.Context, *NoxGetChatImageRequest) (*NoxGetChatImageResponse, error)
	GetImageStorageStats(context.Context, *NoxImageStorageStatsRequest) (*NoxImageStorageStatsResponse, error)
	SweepChatImages(context.Context, *NoxSweepChatImagesRequest) (*NoxSweepChatImagesResponse, error)
	// Chat Files (Unified Workspace storage: IMG, VID, DOC, FILE; chat-bound)
	ListChatFiles(context.Context, *NoxListChatFilesRequest) (*NoxListChatFilesResponse, error)
	GetChatFilePreview(context.Context, *NoxGetChatFilePreviewRequest) (*NoxGetChatFilePreviewResponse, error)
	GetChatFileBytes(context.Context, *NoxGetChatFileBytesRequest) (*NoxGetChatFileBytesResponse, error)
	GetWorkspaceStorageStats(context.Context, *NoxWorkspaceStorageStatsRequest) (*NoxWorkspaceStorageStatsResponse, error)
	SweepChatFiles(context.Context, *NoxSweepChatFilesRequest) (*NoxSweepChatFilesResponse, error)
	// User Profiles & Avatars
	QueryUserProfiles(context.Context, *NoxUserProfileQueryRequest) (*NoxUserProfileQueryResponse, error)
	SearchUserProfiles(context.Context, *NoxUserProfileSearchRequest) (*NoxUserProfileSearchResponse, error)
	GetUserProfilePhoto(context.Context, *NoxUserProfilePhotoRequest) (*NoxUserProfilePhotoResponse, error)
	// Tips (short prompt tips in their own vector space; scope: global / one chat / one persona)
	ListTips(context.Context, *NoxTipListRequest) (*NoxTipListResponse, error)
	SearchTips(context.Context, *NoxTipSearchRequest) (*NoxTipSearchResponse, error)
	AddTips(context.Context, *NoxAddTipsRequest) (*NoxAddTipsResponse, error)
	UpdateTip(context.Context, *NoxUpdateTipRequest) (*NoxTipMutationResponse, error)
	DeleteTips(context.Context, *NoxDeleteTipsRequest) (*NoxTipMutationResponse, error)
	TestTips(context.Context, *NoxTestTipsRequest) (*NoxTestTipsResponse, error)
	// Sandbox administration (Python sandbox_* control RPCs).
	ListSandboxVms(context.Context, *NoxSandboxListVmsRequest) (*NoxSandboxListVmsResponse, error)
	SandboxVmAction(context.Context, *NoxSandboxVmActionRequest) (*NoxSandboxVmActionResponse, error)
	ListSandboxFiles(context.Context, *NoxSandboxListFilesRequest) (*NoxSandboxListFilesResponse, error)
	ReadSandboxText(context.Context, *NoxSandboxReadTextRequest) (*NoxSandboxReadTextResponse, error)
	PreviewSandboxFile(context.Context, *NoxSandboxPreviewFileRequest) (*NoxSandboxPreviewFileResponse, error)
	ListSandboxBackups(context.Context, *NoxSandboxListBackupsRequest) (*NoxSandboxListBackupsResponse, error)
	RestoreSandboxBackup(context.Context, *NoxSandboxRestoreBackupRequest) (*NoxSandboxRestoreBackupResponse, error)
	ListSandboxLibraryRequests(context.Context, *NoxSandboxListLibraryRequestsRequest) (*NoxSandboxListLibraryRequestsResponse, error)
	DecideSandboxLibrary(context.Context, *NoxSandboxDecideLibraryRequest) (*NoxSandboxDecideLibraryResponse, error)
	GetSandboxImageStatus(context.Context, *NoxSandboxImageStatusRequest) (*NoxSandboxImageStatusResponse, error)
	RebuildSandboxImage(context.Context, *NoxSandboxRebuildImageRequest) (*NoxSandboxRebuildImageResponse, error)
	ListSandboxRuns(context.Context, *NoxSandboxListRunsRequest) (*NoxSandboxListRunsResponse, error)
	// Automation: preprocessors and crons (plans/2026-11-20-preprocessors-crons/contracts.md §8)
	GetAutomationStatus(context.Context, *NoxAutomationStatusRequest) (*NoxAutomationStatusResponse, error)
	ListPreprocessors(context.Context, *NoxListPreprocessorsRequest) (*NoxListPreprocessorsResponse, error)
	GetPreprocessor(context.Context, *NoxGetPreprocessorRequest) (*NoxGetPreprocessorResponse, error)
	PreprocessorAction(context.Context, *NoxPreprocessorActionRequest) (*NoxAutomationActionResponse, error)
	ListPreprocessorLogs(context.Context, *NoxListPreprocessorLogsRequest) (*NoxListPreprocessorLogsResponse, error)
	ListCrons(context.Context, *NoxListCronsRequest) (*NoxListCronsResponse, error)
	CronAction(context.Context, *NoxCronActionRequest) (*NoxAutomationActionResponse, error)
	// Per-user LLM quotas (Python quota_* control RPCs)
	ListUserQuotas(context.Context, *NoxListUserQuotasRequest) (*NoxListUserQuotasResponse, error)
	GetUserQuota(context.Context, *NoxGetUserQuotaRequest) (*NoxGetUserQuotaResponse, error)
	SetUserQuota(context.Context, *NoxSetUserQuotaRequest) (*NoxSetUserQuotaResponse, error)
	mustEmbedUnimplementedNoxChatControlServiceServer()
}

